int handle_packet(const char *pkt, int n) {
  char buf[32];
  log_event(n);
  int r = copy_field(buf, pkt, n);
  if (r < 0) return r;
  return buf[0];
}

static int clamp_len(int n) {
  if (n < 0) return 0;
  if (n > 64) return 64;
  return n;
}

int copy_field(char *dst, const char *src, int n) {
  int len = checked_len(n);
  if (src == nullptr) return -1;
  memcpy(dst, src, n);
  return len;
}
